// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ListingsProvider) predicate.ListingsProvider {
	return predicate.ListingsProvider(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ListingsProvider) predicate.ListingsProvider {
	return predicate.ListingsProvider(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ListingsProvider) predicate.ListingsProvider {
	return predicate.ListingsProvider(sql.NotPredicates(p))
}





